import React from 'react';

const Header: React.FC = () => {
  return (
    <header className="text-center mb-20" style={{ padding: '40px 0' }}>
      <h1 style={{ 
        fontSize: '2.2rem', 
        fontWeight: '800', 
        color: '#1e293b', 
        marginBottom: '8px',
      }}>
        <span style={{ 
          background: 'linear-gradient(90deg, #3b82f6, #10b981)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          fontWeight: '900',
          marginRight: '12px'
        }}>
          ZIGZAG
        </span>
        🎨 배너 제작 도우미
      </h1>
      <p style={{ 
        fontSize: '1.1rem', 
        color: '#475569', 
        fontWeight: '400',
      }}>
        셀러님이 배너를 만들 때 필요한 디자인 꿀팁을 안내해드릴게요
      </p>
    </header>
  );
};

export default Header;
